import { ArrowUpRight } from "lucide-react"

import { ResumeRow } from "../components/resume-row"
import { ResumeSection } from "../components/resume-section"
import { portfolio } from "../lib/portfolio"

export default function HomePage() {
  return (
    <div className="flex flex-col gap-12">
      <ResumeSection title="About">
        <p className="text-sm leading-relaxed text-muted-foreground">
          {portfolio.about}
        </p>
      </ResumeSection>

      <ResumeSection title="Work Experience">
        {portfolio.experience.map((job) => (
          <ResumeRow key={`${job.company}-${job.dates}`} date={job.dates}>
            <div className="flex flex-col gap-1">
              <p className="text-sm font-medium text-foreground">
                {job.role} at{" "}
                <a
                  href={job.href}
                  target="_blank"
                  rel="noreferrer"
                  className="hover:underline"
                >
                  {job.company}
                </a>
              </p>
              {job.location ? (
                <p className="text-sm text-muted-foreground">{job.location}</p>
              ) : null}
              <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
                {job.description}
              </p>
            </div>
          </ResumeRow>
        ))}
      </ResumeSection>

      <ResumeSection title="Side Projects">
        {portfolio.projects.map((project) => (
          <ResumeRow key={project.name} date={project.dates}>
            <div className="flex flex-col gap-1">
              <p className="text-sm font-medium text-foreground">
                <a
                  href={project.href}
                  target="_blank"
                  rel="noreferrer"
                  className="hover:underline"
                >
                  {project.name}
                </a>
              </p>
              <p className="text-sm leading-relaxed text-muted-foreground">
                {project.description}
              </p>
            </div>
          </ResumeRow>
        ))}
      </ResumeSection>

      <ResumeSection title="Awards">
        {portfolio.awards.map((award) => (
          <ResumeRow key={`${award.year}-${award.name}`} date={award.year}>
            <p className="text-sm font-medium text-foreground">{award.name}</p>
          </ResumeRow>
        ))}
      </ResumeSection>

      <ResumeSection title="Certifications">
        {portfolio.certificates.map((cert) => (
          <ResumeRow key={`${cert.year}-${cert.name}`} date={cert.year}>
            <p className="text-sm font-medium text-foreground">
              <a
                href={cert.href}
                target="_blank"
                rel="noreferrer"
                className="hover:underline"
              >
                {cert.name}
              </a>
            </p>
          </ResumeRow>
        ))}
      </ResumeSection>

      <ResumeSection title="Education">
        {portfolio.education.map((edu) => (
          <ResumeRow key={`${edu.dates}-${edu.school}`} date={edu.dates}>
            <div className="flex flex-col gap-1">
              <p className="text-sm font-medium text-foreground">{edu.detail}</p>
              <p className="text-sm text-muted-foreground">
                <a
                  href={edu.href}
                  target="_blank"
                  rel="noreferrer"
                  className="hover:underline"
                >
                  {edu.school}
                </a>
              </p>
              {edu.description ? (
                <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
                  {edu.description}
                </p>
              ) : null}
            </div>
          </ResumeRow>
        ))}
      </ResumeSection>

      <ResumeSection title="Contact">
        {portfolio.contact.map((row) => (
          <ResumeRow key={row.label} date={row.label}>
            <a
              href={row.href}
              target={row.href.startsWith("mailto:") ? undefined : "_blank"}
              rel={row.href.startsWith("mailto:") ? undefined : "noreferrer"}
              className="inline-flex items-center gap-1 text-sm font-medium text-foreground hover:underline"
            >
              {row.value}
              <ArrowUpRight className="size-3.5 text-muted-foreground" />
            </a>
          </ResumeRow>
        ))}
      </ResumeSection>
    </div>
  )
}

import { ArrowUpRight } from "lucide-react"
import Link from "next/link"

import { ResumeRow } from "../../components/resume-row"
import { formatWritingDate, getWritingPosts } from "../../lib/writing"

export default function WritingIndexPage() {
  const posts = getWritingPosts()

  return (
    <div className="flex flex-col gap-8" data-resume-page="index">
      <ul className="flex flex-col gap-5">
        {posts.map((post) => (
          <li key={post.slug}>
            <ResumeRow date={formatWritingDate(post.date)}>
              <Link
                href={`/writing/${post.slug}`}
                className="group flex flex-col gap-1"
              >
                <span className="inline-flex items-center gap-1 text-sm font-medium text-foreground group-hover:underline">
                  {post.title}
                  <ArrowUpRight className="size-3.5 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100" />
                </span>
                {post.description ? (
                  <span className="text-sm leading-relaxed text-muted-foreground">
                    {post.description}
                  </span>
                ) : null}
              </Link>
            </ResumeRow>
          </li>
        ))}
      </ul>
    </div>
  )
}

import Link from "next/link"
import { notFound } from "next/navigation"

import {
  formatWritingDate,
  getAdjacentWritingPosts,
  getWritingPost,
  getWritingPosts,
} from "../../../lib/writing"

export function generateStaticParams() {
  return getWritingPosts().map((post) => ({ slug: post.slug }))
}

export default async function WritingEntryPage({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  const post = getWritingPost(slug)
  if (!post) notFound()

  const { prev, next } = getAdjacentWritingPosts(slug)

  return (
    <article className="flex flex-col gap-12">
      <div className="flex flex-col gap-6">
        <Link
          href="/writing"
          data-resume-back
          className="inline-flex w-fit text-sm text-muted-foreground hover:text-foreground"
        >
          ← Back
        </Link>

        <div className="flex items-start justify-between gap-6">
          <div className="min-w-0">
            <h2
              className="text-sm font-semibold tracking-tight text-foreground"
              data-resume-heading
            >
              {post.title}
            </h2>
            {post.description ? (
              <p
                className="mt-2 text-sm text-muted-foreground"
                data-resume-dek
                data-resume-reveal
              >
                {post.description}
              </p>
            ) : null}
          </div>
          <time
            dateTime={post.date}
            data-resume-when
            data-resume-reveal
            className="shrink-0 text-sm tabular-nums text-muted-foreground"
          >
            {formatWritingDate(post.date)}
          </time>
        </div>
      </div>

      <div
        className="flex flex-col gap-5 text-sm leading-relaxed text-muted-foreground"
        data-resume-prose
      >
        {post.body()}
      </div>

      {prev || next ? (
        <nav
          aria-label="Post navigation"
          className="flex items-center justify-between border-t border-border/60 pt-8 text-sm"
        >
          <div>
            {prev ? (
              <Link
                href={`/writing/${prev.slug}`}
                data-resume-prev
                data-resume-reveal
                className="inline-flex text-muted-foreground hover:text-foreground"
              >
                ← Previous
              </Link>
            ) : null}
          </div>
          <div>
            {next ? (
              <Link
                href={`/writing/${next.slug}`}
                data-resume-next
                data-resume-reveal
                className="inline-flex text-muted-foreground hover:text-foreground"
              >
                Next →
              </Link>
            ) : null}
          </div>
        </nav>
      ) : null}
    </article>
  )
}

"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { useLayoutEffect, useRef } from "react"
import gsap from "gsap"

import { cn } from "@/lib/utils"

import { ThemeSwitcher } from "./theme-switcher"

// Path checks use `includes` so the pill still lights up under the host
// preview route (/view/portfolio-v6/writing), not only on a clean install.
const tabs = [
  {
    href: "/",
    label: "About",
    match: (path: string) => !path.includes("/writing"),
  },
  {
    href: "/writing",
    label: "Writing",
    match: (path: string) => path.includes("/writing"),
  },
] as const

export function SiteNav() {
  const pathname = usePathname()
  const navRef = useRef<HTMLElement>(null)
  const tabsRef = useRef<HTMLDivElement>(null)
  const pillRef = useRef<HTMLSpanElement>(null)
  const linkRefs = useRef<(HTMLAnchorElement | null)[]>([])
  const pillPos = useRef({ x: 0, width: 0, primed: false })

  useLayoutEffect(() => {
    const nav = navRef.current
    if (!nav) return

    const mm = gsap.matchMedia()
    mm.add("(prefers-reduced-motion: no-preference)", () => {
      gsap.fromTo(
        nav,
        { y: 14, autoAlpha: 0 },
        { y: 0, autoAlpha: 1, duration: 0.5, ease: "power2.out" }
      )
    })

    return () => mm.revert()
  }, [])

  useLayoutEffect(() => {
    const tabsEl = tabsRef.current
    const pill = pillRef.current
    const activeIndex = tabs.findIndex((tab) => tab.match(pathname))
    const link = linkRefs.current[activeIndex]
    if (!tabsEl || !pill || !link) return

    const x = link.offsetLeft
    const width = link.offsetWidth
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches

    if (!pillPos.current.primed || reduce) {
      gsap.set(pill, { x, width, autoAlpha: 1 })
    } else {
      gsap.to(pill, {
        x,
        width,
        duration: 0.34,
        ease: "power2.out",
        overwrite: "auto",
      })
    }

    pillPos.current = { x, width, primed: true }

    const onResize = () => {
      const current = linkRefs.current[tabs.findIndex((tab) => tab.match(pathname))]
      if (!current) return
      gsap.set(pill, { x: current.offsetLeft, width: current.offsetWidth })
    }

    window.addEventListener("resize", onResize)
    return () => window.removeEventListener("resize", onResize)
  }, [pathname])

  return (
    <div className="pointer-events-none fixed inset-x-0 bottom-6 z-50 flex justify-center px-4">
      <nav
        ref={navRef}
        aria-label="Site"
        className="pointer-events-auto flex items-center gap-3 rounded-full border border-border/60 bg-background/90 p-1 shadow-sm backdrop-blur-md"
      >
        <div ref={tabsRef} className="relative flex items-center">
          <span
            ref={pillRef}
            aria-hidden
            className="absolute top-0 left-0 h-full rounded-full bg-foreground"
          />
          {tabs.map((tab, i) => {
            const active = tab.match(pathname)
            return (
              <Link
                key={tab.href}
                ref={(node) => {
                  linkRefs.current[i] = node
                }}
                href={tab.href}
                aria-current={active ? "page" : undefined}
                className={cn(
                  "relative z-10 rounded-full px-4 py-1.5 text-sm transition-colors",
                  active
                    ? "text-background"
                    : "text-muted-foreground hover:text-foreground"
                )}
              >
                {tab.label}
              </Link>
            )
          })}
        </div>
        <ThemeSwitcher />
      </nav>
    </div>
  )
}

"use client"

import { useLayoutEffect, useRef, type ReactNode } from "react"
import { usePathname } from "next/navigation"
import gsap from "gsap"
import { ScrollTrigger } from "gsap/ScrollTrigger"

gsap.registerPlugin(ScrollTrigger)

function belowFold(el: HTMLElement) {
  return el.getBoundingClientRect().top > window.innerHeight
}

function pageKind(pathname: string): "about" | "index" | "entry" {
  const at = pathname.indexOf("/writing")
  if (at === -1) return "about"
  const rest = pathname
    .slice(at + "/writing".length)
    .replace(/^\/+|\/+$/g, "")
  return rest ? "entry" : "index"
}

function reveal(
  targets: HTMLElement | HTMLElement[],
  trigger: HTMLElement,
  {
    duration = 0.5,
    fromY = 10,
    fromX = 0,
    stagger,
  }: {
    duration?: number
    fromY?: number
    fromX?: number
    stagger?: number
  } = {}
) {
  gsap.set(targets, { autoAlpha: 0, y: fromY, x: fromX })
  gsap.to(targets, {
    autoAlpha: 1,
    y: 0,
    x: 0,
    duration,
    stagger,
    ease: "power2.out",
    overwrite: "auto",
    clearProps: "transform,opacity,visibility",
    scrollTrigger: {
      trigger,
      start: "top 92%",
      once: true,
    },
  })
}

function enterItems(
  items: HTMLElement[],
  { fromX = 0, fromY = 10, stagger = 0.07, duration = 0.48, at = 0 },
  tl: gsap.core.Timeline
) {
  if (!items.length) return
  gsap.set(items, { autoAlpha: 0, x: fromX, y: fromY })
  tl.to(
    items,
    {
      autoAlpha: 1,
      x: 0,
      y: 0,
      duration,
      stagger,
      ease: "power2.out",
      overwrite: "auto",
      clearProps: "transform,opacity,visibility",
    },
    at
  )
}

function setupEnter(
  root: HTMLElement,
  kind: "about" | "index" | "entry",
  fromX: number
) {
  const main = root.querySelector("main")
  if (!main) return

  const tl = gsap.timeline({ defaults: { ease: "power2.out" } })
  const back = main.querySelector<HTMLElement>("[data-resume-back]")
  const heading = main.querySelector<HTMLElement>("[data-resume-heading]")
  const when = main.querySelector<HTMLElement>("[data-resume-when]")
  const dek = main.querySelector<HTMLElement>("[data-resume-dek]")
  const grafs = gsap
    .utils.toArray<HTMLElement>("[data-resume-prose] p", main)
    .filter((el) => !belowFold(el))
  const rows = gsap
    .utils.toArray<HTMLElement>("[data-resume-row]", main)
    .filter((el) => !belowFold(el))
  const headings = gsap
    .utils.toArray<HTMLElement>("[data-resume-heading]", main)
    .filter((el) => !belowFold(el))

  if (kind === "entry") {
    if (back) enterItems([back], { fromX: fromX || -6, fromY: 0, duration: 0.36 }, tl)
    const head = [heading, when].filter(Boolean) as HTMLElement[]
    enterItems(head, { fromX, fromY: 8, duration: 0.42, stagger: 0.05, at: 0.04 }, tl)
    if (dek) enterItems([dek], { fromX, fromY: 8, duration: 0.45, at: 0.1 }, tl)
    enterItems(grafs, { fromX, fromY: 10, duration: 0.5, stagger: 0.08, at: 0.16 }, tl)
    return
  }

  if (kind === "index") {
    enterItems(rows, { fromX, fromY: 10, duration: 0.46, stagger: 0.06, at: 0 }, tl)
    return
  }

  enterItems(headings, { fromX: 0, fromY: 8, duration: 0.42, stagger: 0.05, at: 0 }, tl)
  enterItems(rows, { fromX: 0, fromY: 10, duration: 0.46, stagger: 0.05, at: 0.06 }, tl)
}

function setupStory(root: HTMLElement) {
  const header = root.querySelector<HTMLElement>("[data-resume-header]")
  const avatar = root.querySelector<HTMLElement>("[data-resume-avatar]")
  const main = root.querySelector("main") ?? root
  const headings = gsap.utils.toArray<HTMLElement>("[data-resume-heading]", main)
  const rows = gsap.utils.toArray<HTMLElement>("[data-resume-row]", main)
  const paragraphs = gsap.utils.toArray<HTMLElement>("[data-resume-prose] p", main)
  const extras = gsap.utils.toArray<HTMLElement>("[data-resume-reveal]", main)

  if (avatar && header) {
    gsap.to(avatar, {
      y: 14,
      ease: "none",
      scrollTrigger: {
        trigger: root,
        start: "top top",
        end: "+=45%",
        scrub: 0.8,
      },
    })
  }

  headings.forEach((heading) => {
    if (!belowFold(heading)) return
    reveal(heading, heading, { duration: 0.45, fromY: 8 })
  })

  rows.forEach((row) => {
    if (!belowFold(row)) return
    const date = row.querySelector<HTMLElement>("[data-resume-date]")
    const copy = row.querySelector<HTMLElement>("[data-resume-copy]")
    const bits = [date, copy].filter(Boolean) as HTMLElement[]
    if (!bits.length) {
      reveal(row, row)
      return
    }
    reveal(bits, row, { stagger: 0.06, duration: 0.48, fromY: 10 })
  })

  paragraphs.forEach((paragraph) => {
    if (!belowFold(paragraph)) return
    reveal(paragraph, paragraph, { duration: 0.55, fromY: 10 })
  })

  extras.forEach((el) => {
    if (!belowFold(el)) return
    reveal(el, el, { duration: 0.45, fromY: 8 })
  })

  requestAnimationFrame(() => {
    ScrollTrigger.refresh()
  })
}

function setupNavHover(root: HTMLElement) {
  const cleanups: Array<() => void> = []

  const bind = (el: HTMLElement | null, hoverX: number) => {
    if (!el) return
    const xTo = gsap.quickTo(el, "x", { duration: 0.22, ease: "power2.out" })
    const onEnter = () => xTo(hoverX)
    const onLeave = () => xTo(0)
    el.addEventListener("mouseenter", onEnter)
    el.addEventListener("mouseleave", onLeave)
    el.addEventListener("focus", onEnter)
    el.addEventListener("blur", onLeave)
    cleanups.push(() => {
      el.removeEventListener("mouseenter", onEnter)
      el.removeEventListener("mouseleave", onLeave)
      el.removeEventListener("focus", onEnter)
      el.removeEventListener("blur", onLeave)
    })
  }

  bind(root.querySelector("[data-resume-back]"), -4)
  bind(root.querySelector("[data-resume-prev]"), -4)
  bind(root.querySelector("[data-resume-next]"), 4)

  return () => {
    cleanups.forEach((fn) => fn())
  }
}

export function GsapAnimation({
  children,
  className,
}: {
  children: ReactNode
  className?: string
}) {
  const rootRef = useRef<HTMLDivElement>(null)
  const pathname = usePathname()
  const firstLoadRef = useRef(true)
  const prevKindRef = useRef<ReturnType<typeof pageKind> | null>(null)

  useLayoutEffect(() => {
    const root = rootRef.current
    if (!root) return

    const kind = pageKind(pathname)
    const prev = prevKindRef.current
    const firstLoad = firstLoadRef.current
    firstLoadRef.current = false
    prevKindRef.current = kind

    const fromX =
      prev === "index" && kind === "entry"
        ? 8
        : prev === "entry" && kind === "index"
          ? -8
          : prev === "entry" && kind === "entry"
            ? 8
            : 0

    const mm = gsap.matchMedia()
    mm.add("(prefers-reduced-motion: no-preference)", () => {
      if (!firstLoad || kind !== "about") {
        setupEnter(root, kind, fromX)
      }
      setupStory(root)
      return setupNavHover(root)
    })

    return () => mm.revert()
  }, [pathname])

  return (
    <div ref={rootRef} className={className}>
      {children}
    </div>
  )
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

export function ResumeSection({
